const short=(x?:string)=>x?x.slice(0,6)+'…'+x.slice(-4):'Not connected';
const fmt=(value?:string|number,digits=6)=>value===undefined?'—':Number(value).toLocaleString('en-GB',{maximumFractionDigits:digits});
