 useEffect(()=>{mounted.current=true;try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){const c=validateConfig(saved.config);profiles.current=validateProfiles(saved.profiles,c);setConfig(c);setDraft(c);setMarketChain(c.network===42161?'arbitrum':'bsc');if(c.network===97)setTab('overview');setHistory(Array.isArray(saved.history)?saved.history.filter((t:any)=>supportedNetwork(t?.network)).slice(-200):[]);}}catch{setLoadError('Saved settings could not be read. Defaults are loaded; import a valid configuration backup if needed.');}try{if(localStorage.getItem('bsc-arb-scan-mode')==='selected')setScanMode('selected');}catch{}setReady(true);return()=>{mounted.current=false;epoch.current++;localSigner.current?.lock();};},[]);
