 const pending=history.filter(t=>t.network===config.network&&equal(t.owner,account)&&['pending','confirming','unknown','awaiting-wallet'].includes(t.status));
 async function task(name:string,fn:()=>Promise<any>){if(operationBusy.current||scanBusy.current||allPairsBusy.current)return;operationBusy.current=true;setBusy(name);try{return await fn();}catch(e){notify((e as Error).message,true);}finally{operationBusy.current=false;setBusy('');}}
 async function connect(){await task('Connecting wallet',async()=>{const injected=(window as any).ethereum as Provider|undefined;if(!injected)throw Error('No browser wallet found. Open this site in a browser with MetaMask, Rabby or another EVM wallet, or import your seed locally from Wallets.');const next=injected.providers?.find(p=>p.isMetaMask)||injected;const accounts=await next.request({method:'eth_requestAccounts'});localSigner.current?.lock();localSigner.current=null;provider.current=next;setSignerMode('external');setLive(false);setMonitor(false);setPreview(null);epoch.current++;setAccount(accounts[0]||'');setWalletChain(Number(await provider.current.request({method:'eth_chainId'})));notify('Wallet connected. Keys remain in your wallet.');});}
