 function activateLocal(wallet:EvmWallet){localSigner.current?.lock();const signer=new LocalSigner(wallet,(method,params)=>api('rpc',active.current,{method,params}));localSigner.current=signer;provider.current=signer;setSignerMode('local');setAccount(wallet.address);setWalletChain(active.current.network);setAllPairsStop(n=>n+1);epoch.current++;setMonitor(false);setLive(false);setPreview(null);setDiag(null);setReview(null);lastInteraction.current=Date.now();}
