 async function quoteMarket(pair:Pair):Promise<Scan>{if(operationBusy.current||scanBusy.current||allPairsBusy.current)throw Error('Finish the current scan or wallet action first.');const token=intermediate(pair);if(pair.chain==='solana'||!token||config.network!==MARKET_CHAINS[pair.chain].network)throw Error('Choose the matching mainnet and a wrapped-native pair.');operationBusy.current=true;setBusy('Quoting discovered token');const id=epoch.current;try{const result=await api('scan',config,{assets:[{...token,enabled:true}]}) as Scan;if(id!==epoch.current)throw Error('Network or configuration changed. Requote this token.');setScan(result);return result;}finally{operationBusy.current=false;setBusy('');}}
 function exportHistory(){const rows=[['time','network','kind','owner','status','hash','gas_cost','gas_currency','user_profit','profit_currency']];history.forEach(t=>rows.push([t.createdAt,String(t.network),t.kind,t.owner,t.status,t.hash||'',t.receipt?.cost||t.cost,NETWORKS[t.network].nativeSymbol,t.receipt?.events?.[0]?.profit||'',NETWORKS[t.network].wrappedSymbol]));download('arb-history.csv',rows.map(row=>row.map(csv).join(',')).join('\r\n'),'text/csv');notify('Transaction history exported.');}
